'use strict';

/**
 * End-to-end Placement Test flow against the local emulators with a real
 * Auth-emulator sign-in, replaying the app's exact payloads
 * (`fixtures/placement_client_payloads.json`, generated by
 * test/placement_client_payloads_test.dart): research attempt → answers →
 * submit → in-rules K2 scoring with the app's six proposals → participant
 * band → offline export; then a learning-only retake after study closure
 * that leaves the research record untouched. Synthetic key only.
 */

const { describe, it, before, after } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const os = require('os');
const path = require('path');
const crypto = require('crypto');

const emulatorHost = process.env.FIRESTORE_EMULATOR_HOST || '';
const authHost = process.env.FIREBASE_AUTH_EMULATOR_HOST || '';
const projectId = process.env.GCLOUD_PROJECT || '';
const RUN = /^(127\.0\.0\.1|localhost):\d+$/.test(emulatorHost) && /^(127\.0\.0\.1|localhost):\d+$/.test(authHost) && projectId.startsWith('demo-');

const REPO_ROOT = path.join(__dirname, '..', '..', '..', '..');
const fixture = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'fixtures', 'placement_client_payloads.json'), 'utf8'));
const bankJson = fs.readFileSync(path.join(REPO_ROOT, 'assets', 'placement', 'placement_bank_pt_v1_1.json'), 'utf8').replace(/\r\n/g, '\n');
const bank = JSON.parse(bankJson);
const bankSha256 = crypto.createHash('sha256').update(bankJson).digest('hex');
const LETTERS = ['A', 'B', 'C', 'D'];
const syntheticKeyFile = () => ({
  warning: 'synthetic test key',
  instrumentVersion: bank.instrumentVersion,
  bankSha256,
  key: Object.fromEntries(bank.items.map((i) => [i.id, LETTERS[i.number % 4]])),
});
const EMAIL = 'placement.e2e@example.test';
const PASSWORD = 'placement-e2e-password';

describe('placement app payloads and full flow (emulators, real Auth emulator sign-in)', { skip: !RUN && 'not inside the emulators (npm run test:rules)' }, () => {
  let admin;
  let ops;
  let pops;
  let fsdk;
  let rut;
  const apps = [];

  before(async () => {
    rut = require('@firebase/rules-unit-testing');
    fsdk = require('firebase/firestore');
    ops = require('../../lib/admin/operations');
    pops = require('../../lib/admin/placementOperations');
    const { resolveTarget, initAdmin } = require('../../lib/admin/target');
    admin = initAdmin(resolveTarget({ emulator: true }, { env: process.env, repoRoot: REPO_ROOT }));
    const env = await rut.initializeTestEnvironment({ projectId, firestore: { rules: fs.readFileSync(path.join(REPO_ROOT, 'firestore.rules'), 'utf8') } });
    await env.clearFirestore();
    await env.cleanup();

    await admin.auth.createUser({ uid: fixture.uid, email: EMAIL, password: PASSWORD });
    const { FieldValue } = require('firebase-admin/firestore');
    await admin.db.collection('users').doc(fixture.uid).set({
      uid: fixture.uid, email: EMAIL, name: 'PT E2E', role: 'siswa', createdAt: FieldValue.serverTimestamp(),
      cefrLevel: null, placementTestCompleted: false, placementTestPrompted: true,
    });
    await admin.db.collection('researchParticipants').doc(fixture.uid).set({
      researchId: 'PT-01', band: null, bandSource: null, status: 'awaiting_placement', exclusionReason: null,
      placementAttemptId: null, reviewStatus: null, instrumentVersion: 'v1',
      authorizedAttempts: { placement: 1, preTest: 0, postTest: 0 }, cohort: 'test',
      createdAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp(),
    });
    await pops.seedPlacement(admin.db, { bank, bankSha256, keyFile: syntheticKeyFile(), apply: true });
    await pops.setStudyStatus(admin.db, { status: 'active', apply: true });
  });

  after(async () => {
    for (const app of apps) await require('firebase/app').deleteApp(app);
    await admin.app.delete();
  });

  async function signedInClient() {
    const { initializeApp } = require('firebase/app');
    const { getAuth, connectAuthEmulator, signInWithEmailAndPassword } = require('firebase/auth');
    const app = initializeApp({ projectId, apiKey: 'demo-api-key' }, `pt-client-${apps.length}`);
    apps.push(app);
    const auth = getAuth(app);
    connectAuthEmulator(auth, `http://${authHost}`, { disableWarnings: true });
    const [host, port] = emulatorHost.split(':');
    const db = fsdk.getFirestore(app);
    fsdk.connectFirestoreEmulator(db, host, Number(port));
    await signInWithEmailAndPassword(auth, EMAIL, PASSWORD);
    return db;
  }

  const TS = fixture.serverTimestampMarker;
  const withTs = (v) =>
    v === TS ? fsdk.serverTimestamp() : Array.isArray(v) ? v.map(withTs) : v && typeof v === 'object' ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, withTs(x)])) : v;
  const argsOf = (payload) => {
    const args = [];
    for (const [k, v] of Object.entries(payload)) args.push(k.startsWith('fieldPath:') ? new fsdk.FieldPath(...k.slice(10).split('/')) : k, withTs(v));
    return args;
  };
  const update = (db, id, payload) => fsdk.updateDoc(fsdk.doc(db, 'placementAttempts', id), ...argsOf(payload));
  const stored = async (col, id) => (await admin.db.collection(col).doc(id).get()).data();

  /** Tries the app's six proposals in order, as PlacementService.score does. */
  async function score(db, block) {
    const accepted = [];
    for (const proposal of block.scoreProposals) {
      const batch = fsdk.writeBatch(db);
      batch.update(fsdk.doc(db, 'placementAttempts', block.attemptId), withTs(proposal.attempt));
      batch.update(fsdk.doc(db, 'users', fixture.uid), withTs(proposal.user));
      if (proposal.participant) batch.update(fsdk.doc(db, 'researchParticipants', fixture.uid), withTs(proposal.participant));
      try {
        await batch.commit();
        accepted.push(proposal.attempt.resultLevel + (proposal.attempt.belowA1Threshold ? '*' : ''));
      } catch (error) {
        assert.equal(error.code, 'permission-denied');
      }
    }
    return accepted;
  }

  it('runs placement → scoring → band → export, then a learning retake that never touches research data', async () => {
    const r = fixture.research;
    let db = await signedInClient();

    // Window closed: no attempt. Researcher opens it.
    await rut.assertFails(fsdk.setDoc(fsdk.doc(db, 'placementAttempts', r.attemptId), withTs(r.create)));
    // A get on the missing attempt is refused too (`resource.data` has no value);
    // the app's own-attempts query is what can see it is absent (`start()`).
    await rut.assertFails(fsdk.getDoc(fsdk.doc(db, 'placementAttempts', r.attemptId)));
    const none = await rut.assertSucceeds(fsdk.getDocs(fsdk.query(fsdk.collection(db, 'placementAttempts'), fsdk.where('studentId', '==', fixture.uid))));
    assert.equal(none.size, 0);
    await pops.setStageWindow(admin.db, { stage: 'placement', open: true, apply: true });
    await rut.assertSucceeds(fsdk.setDoc(fsdk.doc(db, 'placementAttempts', r.attemptId), withTs(r.create)));
    await rut.assertFails(fsdk.setDoc(fsdk.doc(db, 'placementAttempts', r.attemptId), withTs(r.create)));

    for (const a of r.answers.slice(0, 20)) await rut.assertSucceeds(update(db, r.attemptId, a.update));
    await rut.assertSucceeds(update(db, r.attemptId, r.tabSwitch));

    // Interruption: researcher closes the window; answers kept; reopen and resume on a new client.
    await pops.setStageWindow(admin.db, { stage: 'placement', close: true, apply: true });
    await rut.assertFails(update(db, r.attemptId, r.answers[20].update));
    await pops.setStageWindow(admin.db, { stage: 'placement', open: true, apply: true });
    db = await signedInClient();
    const resumed = (await fsdk.getDocs(fsdk.query(fsdk.collection(db, 'placementAttempts'), fsdk.where('studentId', '==', fixture.uid)))).docs[0].data();
    assert.deepEqual(resumed.itemOrder, r.create.itemOrder);
    assert.equal(Object.keys(resumed.answers).length, 20);

    await rut.assertFails(update(db, r.attemptId, r.submit)); // 20 of 50
    for (const a of r.answers.slice(20)) await rut.assertSucceeds(update(db, r.attemptId, a.update));
    await rut.assertSucceeds(update(db, r.attemptId, r.changeFirstAnswer)); // answers may change before submit
    await rut.assertSucceeds(update(db, r.attemptId, r.submit));
    await rut.assertFails(update(db, r.attemptId, r.answers[0].update)); // frozen

    // Close the window before scoring: a submission accepted before closure is still scored.
    await pops.setStageWindow(admin.db, { stage: 'placement', close: true, apply: true });
    const accepted = await score(db, r);
    assert.equal(accepted.length, 1, `exactly one proposal accepted, got ${accepted}`);
    assert.deepEqual(await score(db, r), [], 'scored only once');

    const { bandScores, decide } = require('../../lib/placement/scoring');
    const attempt = await stored('placementAttempts', r.attemptId);
    const bandOf = Object.fromEntries(bank.items.map((i) => [i.id, i.band]));
    const expected = decide(bandScores(attempt.answers, syntheticKeyFile().key, bandOf));
    assert.equal(attempt.resultLevel, expected.resultLevel);
    assert.equal(attempt.belowA1Threshold, expected.belowA1Threshold);
    const participant = await stored('researchParticipants', fixture.uid);
    assert.equal(participant.band, expected.pretestTargetBand);
    const [statusRow] = await ops.stageStatus(admin.db, { uid: fixture.uid });
    assert.equal(
      ops.formatPlacementStatus(statusRow.placement),
      `placement=#1 scored answered=50/50 level=${expected.resultLevel}${expected.belowA1Threshold ? '*' : ''} targetBand=${expected.pretestTargetBand ?? 'none'}`
    );
    assert.equal(participant.status, expected.pretestTargetBand ? 'enrolled' : 'excluded');
    assert.equal((await stored('users', fixture.uid)).resultLevel, expected.resultLevel);
    for (const field of ['bandScores', 'flags', 'totalScore']) assert.ok(!(field in attempt));

    // Offline export with the synthetic key.
    const { run } = require('../../bin/export_placement');
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'vocably-pt-'));
    const keyPath = path.join(dir, 'synthetic_placement_key.private.json');
    fs.writeFileSync(keyPath, JSON.stringify(syntheticKeyFile()));
    const outDir = fs.mkdtempSync(path.join(os.tmpdir(), 'vocably-pt-out-'));
    const result = await run(['--emulator', '--key', keyPath, '--out-dir', outDir], { log: () => {} });
    assert.equal(result.attemptRows.length, 1);
    const row = result.attemptRows[0];
    assert.equal(row.offline_check, 'match');
    assert.equal(row.research_id, 'PT-01');
    assert.equal(row.tab_switch_count, 1);
    assert.equal(result.itemRows.length, 50);
    assert.ok(fs.existsSync(path.join(outDir, 'placement_manifest.json')));
    await assert.rejects(run(['--emulator', '--key', keyPath, '--out-dir', outDir], { log: () => {} }), /overwrite/);

    // After the study closes: a learning-only retake updates users.resultLevel only.
    const l = fixture.learning;
    await pops.setLearningPlacement(admin.db, { open: true, apply: true });
    await pops.setStudyStatus(admin.db, { status: 'closed', apply: true });
    await rut.assertSucceeds(fsdk.setDoc(fsdk.doc(db, 'placementAttempts', l.attemptId), withTs(l.create)));
    for (const a of l.answers) await rut.assertSucceeds(update(db, l.attemptId, a.update));
    await rut.assertSucceeds(update(db, l.attemptId, l.submit));
    assert.equal((await score(db, l)).length, 1);
    const after = await stored('researchParticipants', fixture.uid);
    assert.deepEqual([after.band, after.status, after.placementAttemptId], [participant.band, participant.status, r.attemptId]);
    assert.equal((await stored('users', fixture.uid)).resultAttemptId, l.attemptId);
  });
});
